// --------------------------------------------------------
// Available seasons
// --------------------------------------------------------

export function getAvailableSeasons() {
    return Object.keys(NFL_PLAYERS)
        .map(Number)
        .sort((a, b) => a - b);
}


// --------------------------------------------------------
// Get one player
// --------------------------------------------------------

export function getPlayerFromDatabase(
    season,
    playerId
) {
    return (
        NFL_PLAYERS?.[season]?.[playerId] ||
        null
    );
}


// --------------------------------------------------------
// Get all players for one season
// --------------------------------------------------------

export function getPlayersForSeason(
    season
) {
    return Object.values(
        NFL_PLAYERS?.[season] || {}
    );
}


// --------------------------------------------------------
// Find player by name in one season
// --------------------------------------------------------

export function findPlayerByName(
    season,
    playerName
) {
    const target =
        String(
            playerName ||
            ""
        )
            .trim()
            .toLowerCase();


    return (
        getPlayersForSeason(
            season
        ).find(
            (player) =>
                String(
                    player.name ||
                    ""
                )
                    .trim()
                    .toLowerCase() ===
                target
        ) ||
        null
    );
}


// --------------------------------------------------------
// Get every season version of one player
// --------------------------------------------------------

export function getPlayerSeasons(
    playerId
) {
    return getAvailableSeasons()
        .map(
            (season) =>
                getPlayerFromDatabase(
                    season,
                    playerId
                )
        )
        .filter(
            Boolean
        );
}


// --------------------------------------------------------
// Find every season version by name
// --------------------------------------------------------

export function findPlayerAcrossSeasons(
    playerName
) {
    return getAvailableSeasons()
        .map(
            (season) =>
                findPlayerByName(
                    season,
                    playerName
                )
        )
        .filter(
            Boolean
        );
}


// --------------------------------------------------------
// Get teammates from exact historical season
// --------------------------------------------------------

export function getTeammatesForPlayer(
    season,
    playerId
) {
    const player =
        getPlayerFromDatabase(
            season,
            playerId
        );


    if (
        !player
    ) {
        return [];
    }


    const playerTeams =
        new Set(
            player.teams?.length
                ? player.teams
                : [
                    player.team,
                ].filter(
                    Boolean
                )
        );


    return getPlayersForSeason(
        season
    )
        .filter(
            (candidate) => {
                if (
                    candidate.playerId ===
                    player.playerId
                ) {
                    return false;
                }


                const candidateTeams =
                    candidate.teams?.length
                        ? candidate.teams
                        : [
                            candidate.team,
                        ];


                return candidateTeams.some(
                    (team) =>
                        playerTeams.has(
                            team
                        )
                );
            }
        );
}


// --------------------------------------------------------
// Empty player template
// --------------------------------------------------------

export function createEmptyPlayer({
    name = "",
    position = "",
    season = 2025,
    team = "",
    teamName = "",
    playerId = "",
    headshot = "",
    teamLogo = "",
    byeWeek = null
} = {}) {
    return {
        playerId,

        name,

        position,

        season,

        team,

        teamName,

        teams:
            team
                ? [
                    team,
                ]
                : [],

        headshot,

        teamLogo,

        byeWeek,


        averageFantasyPoints:
            0,

        gamesPlayed:
            0,

        totalFantasyPoints:
            0,


        seasonTier:
            "BASE",


        positionRank:
            null,

        positionPlayerCount:
            null,

        positionPercentile:
            null,


        weekly:
            {},

        injuries:
            [],
    };
}
